"""For image data scaled between [-1,1],
    rescale to [0,1] * scale_multiplier (e.g. 255 for RGB images)
    """
def tanh_to_sig_scale(tanh_input: Any, scale_multiplier: Any = 1.0) -> object {
    return (((tanh_input + 1.0) / 2.0) * scale_multiplier);
}

"""Pythagorean Distance Equation.
    Function for counting distance,
    derived from the Pythagorean theorem.
    """
def pythagorean_distance_equation(path1: Any, path2: Any) -> object {
    dotX1 = path1[0];
    dotX2 = path2[0];
    dotY1 = path1[1];
    dotY2 = path2[1];
    result_distance = (((dotX2 - dotX1) ** 2) + ((dotY2 - dotY1) ** 2)) ** 0.5;
    return result_distance;
}

"""Caps the string at 75 characters. If longer than 75 it's capped at max_length-3
    and '...' is appended

    Arguments:
        text {str} -- A text string

    Keyword Arguments:
        max_length {int} -- The maximum number of characters (default: {75})

    Returns:
        str -- The capped string
    """
def _to_short_string(text: str, max_length: int = 75) -> str {
    if (len(text) < max_length) {
        return text;
    }
    return (text[0:72] + "...");
}

"""
	:param sub_s: string, part of the input word
	:param current_dict: list, save words in the dictionary beginning with the entered letters
	:return: boolean
	"""
def has_prefix(sub_s: Any, current_dict: Any) -> object {
    cnt = 0;
    for w in current_dict {
        if w.startswith(sub_s) {
            cnt += 1;
        }
    }
    return (cnt > 0);
}

"""Removes the name prefix in checkpoint.

    Basically, when the model is deployed in parallel, the prefix `module.` will
    be added to the saved checkpoint. This function is used to remove the
    prefix, which is friendly to checkpoint loading.

    Args:
        state_dict: The state dict where the variable names are processed.
        prefix: The prefix to remove. (default: `module.`)
    """
def _strip_state_dict_prefix(state_dict: Any, prefix: Any = 'module.') -> object {
    if not all(key.startswith(prefix) for key in state_dict.keys()) {
        return state_dict;
    }
    stripped_state_dict = `dict();
    for key in state_dict {
        stripped_state_dict[key.replace(prefix, '')] = state_dict[key];
    }
    return stripped_state_dict;
}

"""Bit-rotate 0xAB 0xCD into 0xDA 0xBC and bit-invert result"""
def decode_word(byte1: Any, byte2: Any) -> object {
    word = ((byte1 * 256) + byte2) ^ 65535;
    rotated = (word // 16) + ((word % 16) * 4096);
    return ((rotated // 256), (rotated % 256));
}

"""Prime factorication.

    Parameters
    ----------
      n : int
        Value which should be factorized into primes.
    """
def prime_factors(n: Any) -> object {
    i = 2;
    factors = [];
    while ((i * i) <= n) {
        if (n % i) {
            i += 1;
        } else {
            n //= i;
            factors.append(i);
        }
    }
    if (n > 1) {
        factors.append(n);
    }
    return factors;
}

